```rust
use siderite::prelude::*;

#[derive(Deserialize, Validate, Schema)]
struct Greeting {
    shout: Option<bool>,
}

#[derive(Serialize, Deserialize, Validate, Schema)]
struct Message {
    #[field(min_length = 1, max_length = 280)]
    message: String,
}

/// Plain-text greeting.
#[get("/")]
async fn index() -> PlainText<&'static str> {
    PlainText("Hello, siderite!")
}

/// Greet somebody by name.
#[get("/hello/{name}", tag = "greetings")]
async fn hello(Path(name): Path<String>, Query(greeting): Query<Greeting>) -> PlainText<String> {
    let text = format!("Hello, {name}!");
    PlainText(if greeting.shout.unwrap_or(false) {
        text.to_uppercase()
    } else {
        text
    })
}

/// Echo the posted message back.
#[post("/echo", tag = "greetings")]
async fn echo(Json(message): Json<Message>) -> Json<Message> {
    Json(message)
}

fn app() -> App {
    App::new()
        .title("Hello World")
        .version("1.0.0")
        .routes(routes![index, hello, echo])
}

#[tokio::main]
async fn main() -> std::process::ExitCode {
    siderite_cli::AppCli::new(app).run().await
}
```

Run it:

```bash
cd examples/hello_world
siderite run
```

Or `cargo run -p hello_world -- run`.

Build an optimized binary with `siderite build --release` (the same as
`cargo build --release -p hello_world`); it lands in `target/release/`.

PostgreSQL/MySQL `connect_with(url, options)` installs mandatory session
settings and replaces `options.after_connect`. SQLx keeps that callback
private, so a constructor cannot recover it for transparent composition.
Other pool settings, including checkout validation, remain in effect.
Use `connect_with_init(url, options, hook)` for custom session setup:

```rust
use siderite_backends::connection_init::ConnectionInit;
use siderite_backends::postgres::PgBackend;
use sqlx::postgres::PgPoolOptions;
use std::sync::Arc;

let hook: ConnectionInit<sqlx::Postgres> = Arc::new(|conn, _| {
    Box::pin(async move {
        sqlx::Executor::execute(conn,
            "SET application_name = 'my-app'").await?;
        Ok(())
    })
});
let backend = PgBackend::connect_with_init(
    &database_url, PgPoolOptions::new(), hook,
).await?;
```

The custom hook runs first on every fresh/replacement connection. Required
UTC (and MySQL SQL-mode/GROUP_CONCAT) settings run afterwards, overriding
conflicting values. A hook must leave no transaction or lock open. Its
failure rejects that physical connection; SQLx retries within the pool
acquisition deadline and controls hook error logging. Callback capture
must be safe across concurrent connections. Wrapping an external pool with
`from_pool` leaves session initialization and reset obligations to its owner.
Native MySQL retains its separate explicit session/lease policy.

```rust
use siderite::orm::Databases;
use siderite::prelude::*;

let app = App::new()
    .database("default", primary)
    .database("replica", replica)
    .route("/books", get(list_books));

async fn list_books(State(dbs): State<Databases>) -> Result<Json<Vec<Book>>, ApiError> {
    let books = dbs.objects::<Book>()?.all().await?;
    Ok(Json(books))
}
```

`App::database(alias, db)` adds one database. `App::databases(Databases)`
replaces the whole registry, including a router; a router set that way
survives later `App::database` calls. `App::database_registry()` returns
the registry. Handlers receive it as `State<Databases>`.

`Databases::new().with(alias, db).with_router(router)` builds a registry by
hand. `"default"` is the alias used whenever no router or caller says
otherwise (`Databases::DEFAULT`).

```rust
use siderite::orm::ModelMeta;
use siderite::orm::router::DatabaseRouter;

struct AppRouter;

impl DatabaseRouter for AppRouter {
    fn db_for_read(&self, model: &ModelMeta) -> Option<&str> {
        match model.table {
            "books" => Some("replica"),
            "events" => Some("analytics"),
            _ => None,
        }
    }

    fn db_for_write(&self, model: &ModelMeta) -> Option<&str> {
        (model.table == "events").then_some("analytics")
    }

    fn allow_migrate(&self, alias: &str, model: &ModelMeta) -> bool {
        (model.table == "events") == (alias == "analytics")
    }
}
```

Every hook has a neutral default: `None` means “use `default`”, and
`allow_migrate` defaults to `true`.

Declared on the model, not as a struct field (there is no column and no
serialized form):

```rust
#[model(
    table = "posts",
    many_to_many(tags(Tag, through_table = "post_tags", related_name = "posts"))
)]
pub struct Post { /* .. */ }

let tags = post.tags(&db);
tags.add([&tag], &db).await?;
tags.remove([&tag], &db).await?;
tags.set([&tag], &db).await?;
tags.clear(&db).await?;
let names = tags.queryset().all().await?;
```

Defaults: `through_table = {table}_{name}`, `source_column =
{snake(Model)}_id`, `target_column = {snake(Target)}_id`. Set both columns
explicitly for a self-referential relation. `through = ThroughModel` uses
an explicit through model whose table is the join table; omit
`through_table` then.

`related_name` adds a reverse queryset on the target (a correlated `EXISTS`
over the join table).

```rust
use siderite::orm::signals::{SignalError, SignalEvent, Signals};
use siderite::prelude::*;
use siderite::receiver;

#[receiver(post_save, model = User)]
async fn audit(user: &User, event: &SignalEvent<'_>) -> Result<(), SignalError> {
    // event.db is the handle of the operation, so writes here run inside
    // the caller's transaction when there is one.
    let _ = (user, event);
    Ok(())
}

let signals = Signals::new();
signals.connect(audit_receiver());
let db = Db::new(backend).with_signals(signals);
```

Accepted names: `pre_save`, `post_save`, `pre_delete`, `post_delete`,
`m2m_changed`. Without the macro, build one with
`Receiver::new::<User, _>(SignalName::PostSave, |user, event| Box::pin(async move { Ok(()) }))`.

`SignalEvent` carries:

| Field | Meaning |
|---|---|
| `kind` | which signal fired, with its payload |
| `db` | the handle the operation runs on (the open transaction, if any) |
| `model` | `&'static ModelMeta` of the instance’s model |
| `relation` | `m2m_changed` only: the relation’s field name on the declaring model |
| `pk_set` | `m2m_changed` only: primary keys of the targets involved (empty for `clear`) |

For `m2m_changed` the receiver is typed on the **declaring** model and gets
the source object, loaded by primary key only when such a receiver is
connected.

```rust
struct Db { tenant: String }

impl Dependency for Db {
    async fn resolve(ctx: &mut ResolveContext<'_>) -> Result<Self, ApiError> {
        let config = ctx.resolve::<Config>().await?;
        Ok(Db { tenant: config.tenant.clone() })
    }
    fn describe(op: &mut Operation, r: &mut SchemaRegistry) { /* OpenAPI */ }
}

async fn handler(db: Depends<Db>) -> String { db.tenant.clone() }
```

`Depends<T>` derefs to `T` and holds an `Arc<T>`.

`Query<PageParams>` (`use siderite::{Page, PageParams};`; they are not in the prelude, so an application's own `Page` type does not clash) reads `?page=N&per_page=M`: a 1-based page (default 1) and a page size from 1 to 100 (default 20). Choose other bounds with `PageParams<MAX, DEFAULT>`, for example `Query<PageParams<500, 50>>`; `1 <= DEFAULT <= MAX` is checked at compile time. Zero, negative, non-numeric or too large values are answered with 422 before the handler runs, other query keys are left to other extractors, and the OpenAPI parameters state the minimum, maximum and defaults.

`Page<T>` is the response body: `items`, `total`, `page`, `per_page` and `total_pages`. `params.fetch(queryset)` runs `QuerySet::paginate` (unchanged: one `COUNT`, then one fetch with `OFFSET`/`LIMIT`) and returns a `Page<M>`; `page.map(f)` and `page.try_map(f)` convert the items (for example to response types), and `Page::from(orm_page)` adapts an ORM page. Its schema is inlined, not named, so pages of different item types never collide in `components.schemas`.

```rust
#[get("/items")]
async fn list_items(
    State(dbs): State<Databases>,
    Query(params): Query<PageParams>,
) -> ApiResult<Json<Page<ItemOut>>> {
    let rows = dbs.objects::<Item>()?.order_by([Item::id.asc()]);
    Ok(Json(params.fetch(rows).await?.map(ItemOut::from)))
}
```

The count and the fetch are two statements: rows written between them can make `total` disagree with the items, and an unordered queryset can show a row on two pages or on none. Order by a unique key, and run both inside a transaction with a snapshot (for example `REPEATABLE READ` on PostgreSQL) when the two must agree. A page past the end has no items and the real `total`.

Implement `FromRequestParts` (or `FromRequest`) and optionally `describe` so
the extractor documents itself:

```rust
struct ApiKey;

impl FromRequestParts for ApiKey {
    async fn from_request_parts(parts: &mut Parts) -> Result<Self, ApiError> { /* .. */ }

    fn describe(op: &mut Operation, r: &mut SchemaRegistry) {
        op.add_parameter(Parameter::new(
            "x-api-key", ParameterLocation::Header, true, r.subschema::<String>(),
        ));
    }
}
```

`IntoResponse::describe` works the same way (`op.add_response(..)`). The
default `describe` documents nothing, so an undocumented extractor still
runs.

For `Option<YourExtractor>` to be `None` when the input is missing, mark
that error with `ApiError::absent()`. Unmarked errors propagate through the
`Option`:

```rust
let key = parts.headers.get("x-api-key").ok_or_else(|| {
    ApiError::new(StatusCode::UNAUTHORIZED, "Not authenticated.").absent()
})?;
```

Types used in bodies, queries, and responses derive `Schema`. Nested types
go through `registry.subschema::<T>()`, so named types become
`components.schemas` entries referenced by `$ref`.

```rust
use siderite::security::{Authenticate, HttpBearer, Security, check_scopes};
use siderite::{ApiError, scopes};
use http::request::Parts;
use std::sync::Arc;

struct VerifiedAccess {
    subject: String,
    scopes: Vec<String>,
}

// Application interface: supply a trusted JWT verifier or introspection
// implementation. There is deliberately no permissive default verifier.
trait AccessVerifier: Send + Sync {
    // Verify signature, allowed algorithm, issuer, audience, expiry,
    // not-before and token type before returning these trusted fields.
    fn verify(&self, token: &str) -> Result<VerifiedAccess, ApiError>;
}

struct CurrentUser(String);

impl Authenticate for CurrentUser {
    type Credentials = HttpBearer;

    async fn authenticate(
        credentials: HttpBearer,
        required: &[&'static str],
        parts: &Parts,
    ) -> Result<Self, ApiError> {
        let verifier = parts.extensions
            .get::<Arc<dyn AccessVerifier>>()
            .ok_or_else(|| ApiError::internal("Verifier not configured."))?;
        let access = verifier.verify(&credentials.token)?;
        check_scopes(required, access.scopes.iter().map(String::as_str))?;
        Ok(CurrentUser(access.subject))
    }
}

scopes!(pub ReadScopes = ["read"]);

async fn me(Security(user, _): Security<CurrentUser, ReadScopes>) -> String {
    user.0
}
```

Install the verifier with `App::with_state(Arc<dyn AccessVerifier>)`.
The interface above shows the ownership boundary; implement it with a
verified token library/provider, not handwritten JWT cryptography.
Integration tests must reject a forged signature, wrong issuer/audience,
expired or not-yet-valid access token, ID-token substitution, missing scope
and untrusted key ID/URL. Test state/nonce replay and redirect mismatch at
the OAuth callback too. These provider checks are application tests;
Siderite's extraction/scopes tests cannot establish their correctness.

`Security<T, S>` extracts `T::Credentials`, calls
`T::authenticate(credentials, S::SCOPES, parts)`, and documents the scheme
together with the scopes. Scopes default to `NoScopes`, so
`Security<CurrentUser>` requires none. The second tuple field is a type
marker: destructure it as `_`.

| Outcome | Status |
|---|---|
| Credentials missing or malformed | 401 with the scheme’s challenge |
| `authenticate` rejects the credentials | whatever `ApiError` you return, normally 401 |
| `check_scopes` finds scopes missing | 403, `Missing required scopes: a, b.` |

`scopes!` declares a marker type implementing `Scopes` because const `&str`
generics are not stable. `check_scopes(required, granted)` is a plain
function you can call from any `Authenticate` implementation.

```rust
#[model_hooks]
impl CreateUser {
    #[field_validator("user_name", mode = "after")]
    fn not_reserved(value: &str) -> Result<(), FieldError> {
        if value == "admin" {
            Err(FieldError::new("reserved", "name is reserved"))
        } else {
            Ok(())
        }
    }

    #[model_validator(mode = "after")]
    fn adult_email(&self) -> Result<(), FieldError> { Ok(()) }

    #[computed_field]
    fn display_name(&self) -> String { format!("@{}", self.user_name) }
}
```

Order:

1. Model before-validators.
2. For each field, in declaration order: before-validators, type `prepare`,
   constraints.
3. Serde deserialization.
4. Field after-validators, in declaration order.
5. Model after-validators.

The derives find `#[model_hooks]` on concrete types without being told. A
**generic** model such as `Page<T>` with hooks must declare
`#[model_config(hooks)]`. Field validators and serializers take
`(value: &FieldTy)`. A reusable `#[field(validator = path)]` runs right
after the field’s own checks, before the `#[model_hooks]` validators.

```rust
use siderite_testkit::TestClient;

let client = TestClient::new(app());
let response = client.get("/users/1").await?;
assert_eq!(response.status, 200);
let user: User = response.json()?;

client.post_json("/users", &NewUser { name: "ann".into() }).await?;
```

`TestClient::new` panics on a misconfigured app (duplicate routes, bad
paths, OpenAPI failures); `try_new` returns the error so a test can assert
on it. Requests: `get`, `delete`, `post_json`,
`post_raw(path, content_type, body)`, and `send(Request<Body>)` for
anything else (`siderite_testkit::http` is re-exported). A `TestResponse`
has `status`, `headers`, `body`, `json::<T>()`, `text()`, and
`content_type()`.

`TestClient::start(app)` also runs the startup hooks, like `App::run`
without a socket; call `shutdown()` to run the shutdown hooks.

//! Authentication: the OAuth2 password flow with opaque tokens kept in a table.
//!
//! * `POST /token` exchanges a username and password for a bearer token.
//! * [`CurrentUser`] resolves that token back to an account, and
//!   `Security<CurrentUser, S>` also enforces the scopes `S` and documents the
//!   scheme in the OpenAPI document.
//!
//! # Security notes
//!
//! **[`hash_password`] is a placeholder and is NOT production password
//! hashing.** It is a salted, iterated FNV-1a digest, chosen only because the
//! example may not add dependencies. A real application must store passwords
//! with a memory-hard algorithm such as Argon2id, scrypt or bcrypt, and
//! compare with a vetted constant-time primitive.
//!
//! Tokens are random (two UUIDv4 values), stored in the clear and expire after
//! [`TOKEN_TTL_HOURS`]. Neither passwords nor tokens are ever logged.

use crate::db::Conn;
use crate::models::{AccessToken, User};
use http::request::Parts;
use siderite::http::header::WWW_AUTHENTICATE;
use siderite::http::{HeaderValue, StatusCode};
use siderite::orm::uuid::Uuid;
use siderite::prelude::*;
use siderite::scopes;
use siderite::security::{
    Authenticate, OAuth2PasswordBearer, OAuth2PasswordRequestForm, OAuth2Spec, check_scopes,
};

/// How long an issued token stays valid.
pub const TOKEN_TTL_HOURS: i64 = 1;

/// Scope required to write posts.
pub const POSTS_WRITE: &str = "posts:write";
/// Scope required to write comments.
pub const COMMENTS_WRITE: &str = "comments:write";
/// Scopes every new account may be granted.
pub const DEFAULT_SCOPES: &str = "posts:write comments:write";

const HASH_PREFIX: &str = "placeholder";
const HASH_ROUNDS: u32 = 10_000;
const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0100_0000_01b3;

/// OAuth2 password flow of this API.
#[derive(Debug, Clone, Copy)]
pub struct BlogAuth;

impl OAuth2Spec for BlogAuth {
    const TOKEN_URL: &'static str = "/token";
    const SCOPES: &'static [(&'static str, &'static str)] = &[
        (POSTS_WRITE, "Create, edit and delete your own posts"),
        (COMMENTS_WRITE, "Comment on posts"),
    ];
    const SCHEME: &'static str = "OAuth2PasswordBearer";
}

scopes!(
    /// Required to create, edit and delete posts.
    pub WritePosts = ["posts:write"]
);
scopes!(
    /// Required to comment.
    pub WriteComments = ["comments:write"]
);

/// The authenticated account behind a valid, unexpired token.
#[derive(Debug, Clone)]
pub struct CurrentUser {
    /// Primary key of the account.
    pub id: i64,
    /// Login name.
    pub username: String,
    /// Scopes granted to the presented token.
    pub scopes: Vec<String>,
}

/// `401` with a `Bearer` challenge.
fn unauthorized(detail: &'static str) -> ApiError {
    ApiError::new(StatusCode::UNAUTHORIZED, detail)
        .with_header(WWW_AUTHENTICATE, HeaderValue::from_static("Bearer"))
}

impl Authenticate for CurrentUser {
    type Credentials = OAuth2PasswordBearer<BlogAuth>;

    async fn authenticate(
        credentials: Self::Credentials,
        required: &[&'static str],
        parts: &Parts,
    ) -> Result<Self, ApiError> {
        let Conn(db) = Conn::from_parts_ref(parts)?;
        let token = AccessToken::objects(&db)
            .filter(AccessToken::token.eq(credentials.token))
            .first()
            .await?
            .filter(|token| token.expires_at > Utc::now())
            .ok_or_else(|| unauthorized("Invalid or expired token."))?;
        check_scopes(required, token.scopes.split_whitespace())?;
        let user = User::objects(&db)
            .filter(User::id.eq(*token.user.id()))
            .first()
            .await?
            .ok_or_else(|| unauthorized("Invalid or expired token."))?;
        Ok(Self {
            id: user.id,
            username: user.username,
            scopes: token.scopes.split_whitespace().map(str::to_owned).collect(),
        })
    }
}

/// Digest of `password` under `salt`: [`HASH_ROUNDS`] rounds of FNV-1a.
///
/// Not a password hash; see the module documentation.
fn digest(salt: &str, password: &str) -> u64 {
    (0..HASH_ROUNDS).fold(FNV_OFFSET, |state, _| {
        salt.bytes()
            .chain(password.bytes())
            .chain(state.to_le_bytes())
            .fold(FNV_OFFSET, |hash, byte| {
                (hash ^ u64::from(byte)).wrapping_mul(FNV_PRIME)
            })
    })
}

/// Hash `password` for storage as `placeholder$<salt>$<digest>`.
///
/// **Placeholder only, NOT production password hashing.** See the module
/// documentation.
pub fn hash_password(password: &str) -> String {
    let salt = Uuid::new_v4().simple().to_string();
    format!("{HASH_PREFIX}${salt}${:016x}", digest(&salt, password))
}

/// Compare two byte strings without stopping at the first difference.
fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    a.len() == b.len() && a.iter().zip(b).fold(0_u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

/// Whether `password` matches a value produced by [`hash_password`].
pub fn verify_password(password: &str, stored: &str) -> bool {
    let mut fields = stored.split('$');
    let (Some(HASH_PREFIX), Some(salt), Some(expected), None) =
        (fields.next(), fields.next(), fields.next(), fields.next())
    else {
        return false;
    };
    let actual = format!("{:016x}", digest(salt, password));
    constant_time_eq(actual.as_bytes(), expected.as_bytes())
}

/// Response of `POST /token` (RFC 6749 section 5.1).
#[derive(Debug, Serialize, Schema)]
pub struct TokenResponse {
    /// The bearer token.
    pub access_token: String,
    /// Always `bearer`.
    pub token_type: String,
    /// Granted scopes, space-separated.
    pub scope: String,
}

/// Scopes to grant: the requested ones, or all the account holds when none
/// were requested.
///
/// # Errors
/// `400` when a requested scope is not one the account holds.
fn granted_scopes(held: &str, requested: &[String]) -> Result<String, ApiError> {
    if requested.is_empty() {
        return Ok(held.to_owned());
    }
    let held: Vec<&str> = held.split_whitespace().collect();
    match requested
        .iter()
        .find(|scope| !held.contains(&scope.as_str()))
    {
        Some(scope) => Err(ApiError::bad_request(format!(
            "Scope `{scope}` is not allowed."
        ))),
        None => Ok(requested.join(" ")),
    }
}

/// Exchange a username and password for a bearer token.
#[post("/token", tag = "auth")]
async fn issue_token(
    Conn(db): Conn,
    form: OAuth2PasswordRequestForm,
) -> Result<Json<TokenResponse>, ApiError> {
    let user = User::objects(&db)
        .filter(User::username.eq(form.username.clone()))
        .first()
        .await?;
    // Verify against a dummy value for unknown users so both failures cost the same.
    let stored = user
        .as_ref()
        .map_or("placeholder$0$0", |user| user.password_hash.as_str());
    let valid = verify_password(&form.password, stored);
    let user = match user {
        Some(user) if valid => user,
        _ => return Err(unauthorized("Incorrect username or password.")),
    };
    let scope = granted_scopes(&user.scopes, &form.scopes)?;
    let token = Uuid::new_v4().simple().to_string() + &Uuid::new_v4().simple().to_string();
    AccessToken::objects(&db)
        .create(AccessToken {
            id: 0,
            token: token.clone(),
            user: ForeignKey::new(user.id),
            scopes: scope.clone(),
            expires_at: Utc::now() + siderite::orm::chrono::Duration::hours(TOKEN_TTL_HOURS),
        })
        .await?;
    Ok(Json(TokenResponse {
        access_token: token,
        token_type: "bearer".to_owned(),
        scope,
    }))
}

/// Routes of this module.
pub fn routes() -> Vec<Route> {
    routes![issue_token].into_iter().collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hashes_verify_and_are_salted() {
        let first = hash_password("correct horse");
        assert!(verify_password("correct horse", &first));
        assert!(!verify_password("wrong", &first));
        assert_ne!(first, hash_password("correct horse"));
        assert!(!first.contains("correct horse"));
    }

    #[test]
    fn malformed_hashes_never_verify() {
        for stored in [
            "",
            "placeholder",
            "x$y$z",
            "placeholder$a$b$c",
            "placeholder$0$0",
        ] {
            assert!(!verify_password("pw", stored));
        }
    }

    #[test]
    fn requested_scopes_must_be_held() {
        let held = "posts:write comments:write";
        assert_eq!(granted_scopes(held, &[]).unwrap_or_default(), held);
        assert_eq!(
            granted_scopes(held, &["posts:write".to_owned()]).unwrap_or_default(),
            "posts:write"
        );
        assert!(granted_scopes(held, &["admin".to_owned()]).is_err());
    }
}

//! Comments on posts.

use crate::auth::{CurrentUser, WriteComments};
use crate::db::Conn;
use crate::models::Comment;
use crate::pagination::{PageParams, Paginated, paginate};
use crate::posts::visible_post;
use siderite::orm::ModelOps;
use siderite::prelude::*;
use siderite::security::Security;

/// A comment as returned to clients.
#[derive(Debug, Serialize, Schema)]
pub struct CommentOut {
    /// Database key.
    pub id: i64,
    /// Primary key of the commenting account.
    pub author_id: i64,
    /// Comment text.
    pub body: String,
    /// When the comment was written (RFC 3339).
    pub created_at: String,
}

impl From<Comment> for CommentOut {
    fn from(comment: Comment) -> Self {
        Self {
            id: comment.id,
            author_id: *comment.author.id(),
            body: comment.body,
            created_at: comment.created_at.to_rfc3339(),
        }
    }
}

/// Body of `POST /posts/{slug}/comments`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct NewComment {
    /// Comment text, 1 to 2000 characters.
    #[field(min_length = 1, max_length = 2000)]
    pub body: String,
}

/// List the comments of a post, oldest first.
#[get("/posts/{slug}/comments", tag = "comments")]
async fn list_comments(
    Conn(db): Conn,
    viewer: Option<Security<CurrentUser>>,
    Path(slug): Path<String>,
    Query(page): Query<PageParams>,
) -> Result<Json<Paginated<CommentOut>>, ApiError> {
    let viewer = viewer.map(|Security(user, _)| user.id);
    let post = visible_post(&db, &slug, viewer).await?;
    let queryset = Comment::objects(&db).filter(Comment::post.eq(post.id));
    let out = paginate(queryset, page, |comment| async move { Ok(comment.into()) }).await?;
    Ok(Json(out))
}

/// Comment on a post; requires the `comments:write` scope.
#[post("/posts/{slug}/comments", status = 201, tag = "comments")]
async fn create_comment(
    Security(user, _): Security<CurrentUser, WriteComments>,
    Conn(db): Conn,
    Path(slug): Path<String>,
    Json(body): Json<NewComment>,
) -> Result<Json<CommentOut>, ApiError> {
    let post = visible_post(&db, &slug, Some(user.id)).await?;
    let mut comment = Comment {
        id: 0,
        post: ForeignKey::new(post.id),
        author: ForeignKey::new(user.id),
        body: body.body,
        created_at: Utc::now(),
    };
    comment.save(&db).await?;
    Ok(Json(comment.into()))
}

/// Routes of this module.
pub fn routes() -> Vec<Route> {
    routes![list_comments, create_comment].into_iter().collect()
}

//! Access to the application database from handlers and authentication.

use http::request::Parts;
use siderite::orm::Databases;
use siderite::prelude::*;
use std::sync::Arc;

/// Handler argument holding the `"default"` database.
///
/// The model signal receivers are attached where the database is created:
/// `AppCli::configure_db` in the binary, `TestDatabase::with_signals` in tests.
#[derive(Debug, Clone)]
pub struct Conn(pub Db);

impl Conn {
    /// Look the database up in the request extensions.
    ///
    /// # Errors
    /// `500` when the app has no `"default"` database registered.
    pub fn from_parts_ref(parts: &Parts) -> Result<Self, ApiError> {
        let db = parts
            .extensions
            .get::<Arc<Databases>>()
            .and_then(|databases| databases.default_db())
            .ok_or_else(|| ApiError::internal("no `default` database registered"))?
            .clone();
        Ok(Self(db))
    }
}

impl FromRequestParts for Conn {
    async fn from_request_parts(parts: &mut Parts) -> Result<Self, ApiError> {
        Self::from_parts_ref(parts)
    }
}

//! A complete blog API on PostgreSQL.
//!
//! Users register, exchange their password for a bearer token (OAuth2 password
//! flow) and write posts and comments; readers browse paginated, tagged posts.
//! Model signals keep an audit trail of post changes.
//!
//! | Module | Content |
//! |---|---|
//! | [`models`] | `User`, `Post`, `Tag`, `Comment`, `AccessToken`, `AuditEntry` |
//! | [`auth`] | token endpoint, [`auth::CurrentUser`], scopes |
//! | [`users`], [`posts`], [`comments`] | the HTTP routes |
//! | [`receivers`] | `post_save` / `post_delete` audit receivers |
//! | [`pagination`] | `?page=&per_page=` and the page envelope |
//!
//! The binary (`src/main.rs`) drives everything through `AppCli`:
//! `makemigrations`, `migrate`, `check`, `routes` and `run`.

pub mod auth;
pub mod comments;
pub mod db;
pub mod models;
pub mod pagination;
pub mod posts;
pub mod receivers;
pub mod users;

use siderite::prelude::*;

/// Environment variable holding the PostgreSQL URL.
pub const DATABASE_URL_ENV: &str = "DATABASE_URL";

/// Directory of the generated migrations (next to this crate's manifest).
pub const MIGRATIONS_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/migrations");

/// The application. The databases are registered by the caller
/// (`AppCli` from settings, tests through the test client builder).
pub fn app() -> App {
    App::new()
        .title("Blog")
        .version("1.0.0")
        .description("Posts, tags and comments with OAuth2 password-flow authentication.")
        .routes(auth::routes())
        .routes(users::routes())
        .routes(posts::routes())
        .routes(comments::routes())
}

//! Blog API command line.
//!
//! ```text
//! export DATABASE_URL=postgres://siderite:siderite@127.0.0.1:55432/siderite
//! cargo run -p blog_postgres -- migrate
//! ADDR=127.0.0.1:18080 cargo run -p blog_postgres -- run
//! ```

use blog_postgres::{DATABASE_URL_ENV, MIGRATIONS_DIR, app, models, receivers};
use siderite_cli::{AppCli, CliSettings};
use std::process::ExitCode;

#[tokio::main]
async fn main() -> ExitCode {
    let mut settings = CliSettings::new();
    if let Ok(url) = std::env::var(DATABASE_URL_ENV) {
        settings = settings.database("default", url);
    }
    AppCli::new(app)
        .models(&models::all_models())
        .settings(settings)
        .migrations_dir(MIGRATIONS_DIR)
        .configure_db(|_, db| db.with_signals(receivers::signals()))
        .run()
        .await
}

//! Database models of the blog.
//!
//! Table names are explicit so the migrations do not depend on how the Rust
//! type names are converted (`user` is a reserved word in PostgreSQL).

use siderite::prelude::*;

/// A registered account.
#[derive(Debug, Clone, Model)]
#[model(table = "users", ordering = ["id"])]
pub struct User {
    /// Database key.
    #[field(primary_key, auto)]
    pub id: i64,
    /// Unique login name.
    #[field(unique, max_length = 32)]
    pub username: String,
    /// Salted password digest (see [`crate::auth::hash_password`]).
    pub password_hash: String,
    /// Space-separated scopes this account may be granted.
    pub scopes: String,
    /// When the account was created.
    #[field(auto_now_add)]
    pub created_at: DateTime<Utc>,
}

/// A blog post; tags are a many-to-many relation.
#[derive(Debug, Clone, Model)]
#[model(
    table = "posts",
    ordering = ["-id"],
    many_to_many(tags(Tag, through_table = "post_tags", related_name = "posts")),
)]
pub struct Post {
    /// Database key.
    #[field(primary_key, auto)]
    pub id: i64,
    /// Headline.
    #[field(max_length = 200)]
    pub title: String,
    /// URL-safe unique identifier derived from the title.
    #[field(unique, max_length = 220)]
    pub slug: String,
    /// Post text.
    pub body: String,
    /// Drafts (`false`) are only visible to their author.
    pub published: bool,
    /// The account that wrote the post.
    #[field(related_name = "posts")]
    pub author: ForeignKey<User>,
    /// When the post was created.
    #[field(auto_now_add)]
    pub created_at: DateTime<Utc>,
    /// When the post was last saved.
    #[field(auto_now)]
    pub updated_at: DateTime<Utc>,
}

/// A label that can be attached to many posts.
#[derive(Debug, Clone, Model)]
#[model(table = "tags", ordering = ["name"])]
pub struct Tag {
    /// Database key.
    #[field(primary_key, auto)]
    pub id: i64,
    /// Unique lower-case name.
    #[field(unique, max_length = 50)]
    pub name: String,
}

/// A reader's comment on a post.
#[derive(Debug, Clone, Model)]
#[model(table = "comments", ordering = ["id"])]
pub struct Comment {
    /// Database key.
    #[field(primary_key, auto)]
    pub id: i64,
    /// The commented post; comments go away with it.
    #[field(related_name = "comments", on_delete = "cascade")]
    pub post: ForeignKey<Post>,
    /// The commenting account.
    #[field(related_name = "comments")]
    pub author: ForeignKey<User>,
    /// Comment text.
    pub body: String,
    /// When the comment was written.
    #[field(auto_now_add)]
    pub created_at: DateTime<Utc>,
}

/// An opaque bearer token issued by `POST /token`.
#[derive(Debug, Clone, Model)]
#[model(table = "access_tokens")]
pub struct AccessToken {
    /// Database key.
    #[field(primary_key, auto)]
    pub id: i64,
    /// The random token value the client sends back.
    #[field(unique, max_length = 64)]
    pub token: String,
    /// The account the token belongs to.
    #[field(related_name = "tokens", on_delete = "cascade")]
    pub user: ForeignKey<User>,
    /// Space-separated scopes granted to this token.
    pub scopes: String,
    /// The token stops working at this instant.
    pub expires_at: DateTime<Utc>,
}

/// One line of the audit trail written by the signal receivers.
#[derive(Debug, Clone, Model)]
#[model(table = "audit_log", ordering = ["id"])]
pub struct AuditEntry {
    /// Database key.
    #[field(primary_key, auto)]
    pub id: i64,
    /// What happened, e.g. `post.created`.
    pub action: String,
    /// Primary key of the affected row.
    pub entity_id: i64,
    /// When it happened.
    #[field(auto_now_add)]
    pub created_at: DateTime<Utc>,
}

/// Every model, in dependency order, for `makemigrations` and tests.
pub fn all_models() -> [&'static siderite::orm::ModelMeta; 6] {
    [
        User::META,
        Tag::META,
        Post::META,
        Comment::META,
        AccessToken::META,
        AuditEntry::META,
    ]
}

//! Page-number pagination shared by every list endpoint.

use siderite::orm::{Model, QuerySet};
use siderite::prelude::*;

/// Page size when the client sends none.
pub const DEFAULT_PER_PAGE: u64 = 20;

/// Query parameters `?page=2&per_page=10`.
#[derive(Debug, Clone, Copy, Deserialize, Validate, Schema)]
pub struct PageParams {
    /// 1-based page number (default 1).
    #[field(ge = 1)]
    pub page: Option<u64>,
    /// Items per page, at most 100 (default 20).
    #[field(ge = 1, le = 100)]
    pub per_page: Option<u64>,
}

impl PageParams {
    /// The requested page, defaulting to the first.
    pub fn page(&self) -> u64 {
        self.page.unwrap_or(1)
    }

    /// The requested page size, defaulting to [`DEFAULT_PER_PAGE`].
    pub fn per_page(&self) -> u64 {
        self.per_page.unwrap_or(DEFAULT_PER_PAGE)
    }
}

/// One page of `T`.
#[derive(Debug, Serialize, Schema)]
pub struct Paginated<T: Schema> {
    /// The items of this page.
    pub items: Vec<T>,
    /// Items over all pages.
    pub total: u64,
    /// 1-based number of this page.
    pub page: u64,
    /// Requested page size.
    pub per_page: u64,
    /// Number of pages.
    pub total_pages: u64,
}

/// Run `queryset` for the requested page and convert each row with `map`.
///
/// # Errors
/// Database errors, or those of `map`.
pub async fn paginate<M, T, F, Fut>(
    queryset: QuerySet<M>,
    params: PageParams,
    map: F,
) -> Result<Paginated<T>, ApiError>
where
    M: Model,
    T: Schema,
    F: Fn(M) -> Fut,
    Fut: std::future::Future<Output = Result<T, ApiError>>,
{
    let page = queryset.paginate(params.page(), params.per_page()).await?;
    let (total, total_pages) = (page.total, page.total_pages());
    let mut items = Vec::with_capacity(page.items.len());
    for row in page.items {
        items.push(map(row).await?);
    }
    Ok(Paginated {
        items,
        total,
        page: page.page,
        per_page: page.per_page,
        total_pages,
    })
}

//! Posts and tags.

use crate::auth::{CurrentUser, WritePosts};
use crate::db::Conn;
use crate::models::{Post, Tag};
use crate::pagination::{PageParams, Paginated, paginate};
use siderite::orm::ModelOps;
use siderite::prelude::*;
use siderite::security::Security;

/// Longest slug stem kept from a title.
const MAX_SLUG_LEN: usize = 200;
/// Most tags one post may carry.
const MAX_TAGS: usize = 10;

/// A post as returned to clients.
#[derive(Debug, Serialize, Schema)]
pub struct PostOut {
    /// Database key.
    pub id: i64,
    /// Headline.
    pub title: String,
    /// URL-safe unique identifier used in `/posts/{slug}`.
    pub slug: String,
    /// Post text.
    pub body: String,
    /// Whether the post is visible to everyone.
    pub published: bool,
    /// Primary key of the author.
    pub author_id: i64,
    /// Tag names.
    pub tags: Vec<String>,
    /// When the post was created (RFC 3339).
    pub created_at: String,
    /// When the post was last saved (RFC 3339).
    pub updated_at: String,
}

/// A tag as returned to clients.
#[derive(Debug, Serialize, Schema)]
pub struct TagOut {
    /// Database key.
    pub id: i64,
    /// Tag name.
    pub name: String,
}

/// Body of `POST /posts`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct NewPost {
    /// Headline.
    #[field(min_length = 1, max_length = 200)]
    pub title: String,
    /// Post text.
    #[field(min_length = 1)]
    pub body: String,
    /// Publish immediately (default `false`: a draft).
    #[serde(default)]
    pub published: bool,
    /// Tag names; created on demand (at most 10).
    #[serde(default)]
    pub tags: Vec<String>,
}

/// Body of `PATCH /posts/{slug}`; absent fields stay unchanged.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct PatchPost {
    /// Replacement headline (the slug does not change).
    #[field(min_length = 1, max_length = 200)]
    pub title: Option<String>,
    /// Replacement text.
    #[field(min_length = 1)]
    pub body: Option<String>,
    /// Replacement visibility.
    pub published: Option<bool>,
    /// Replacement tag names (at most 10).
    pub tags: Option<Vec<String>>,
}

/// Query parameters of `GET /posts`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct PostFilter {
    /// Only posts carrying this tag.
    pub tag: Option<String>,
}

/// Lower-case `title`, keep letters and digits, join words with `-`.
pub fn slugify(title: &str) -> String {
    let mut slug = String::new();
    for c in title.chars().flat_map(char::to_lowercase) {
        if c.is_alphanumeric() {
            slug.push(c);
        } else if !slug.is_empty() && !slug.ends_with('-') {
            slug.push('-');
        }
    }
    let slug: String = slug
        .trim_end_matches('-')
        .chars()
        .take(MAX_SLUG_LEN)
        .collect();
    if slug.is_empty() {
        "post".to_owned()
    } else {
        slug
    }
}

/// A slug for `title` that no post uses yet (`my-title`, `my-title-2`, ...).
async fn unique_slug(db: &Db, title: &str) -> Result<String, ApiError> {
    let stem = slugify(title);
    let mut candidate = stem.clone();
    for n in 2_u32.. {
        if !Post::objects(db)
            .filter(Post::slug.eq(candidate.clone()))
            .exists()
            .await?
        {
            break;
        }
        candidate = format!("{stem}-{n}");
    }
    Ok(candidate)
}

/// Normalize tag names: trimmed, lower-case, no blanks, no duplicates.
///
/// # Errors
/// `400` when more than [`MAX_TAGS`] remain or one is longer than 50 characters.
fn clean_tags(names: &[String]) -> Result<Vec<String>, ApiError> {
    let mut cleaned: Vec<String> = Vec::new();
    for name in names {
        let name = name.trim().to_lowercase();
        if name.is_empty() || cleaned.contains(&name) {
            continue;
        }
        if name.chars().count() > 50 {
            return Err(ApiError::bad_request("A tag is at most 50 characters."));
        }
        cleaned.push(name);
    }
    if cleaned.len() > MAX_TAGS {
        return Err(ApiError::bad_request(format!(
            "A post has at most {MAX_TAGS} tags."
        )));
    }
    Ok(cleaned)
}

/// Make `names` the complete tag set of `post`, creating missing tags.
async fn replace_tags(db: &Db, post: &Post, names: &[String]) -> Result<(), ApiError> {
    let mut keys = Vec::with_capacity(names.len());
    for name in names {
        let (tag, _) = Tag::objects(db)
            .get_or_create(Tag::name.eq(name.clone()), || Tag {
                id: 0,
                name: name.clone(),
            })
            .await?;
        keys.push(tag.id);
    }
    post.tags(db).set_pks(keys).await?;
    Ok(())
}

/// Convert `post` to its response form.
pub async fn post_out(db: &Db, post: Post) -> Result<PostOut, ApiError> {
    let tags = post
        .tags(db)
        .queryset()
        .all()
        .await?
        .into_iter()
        .map(|tag| tag.name)
        .collect();
    Ok(PostOut {
        id: post.id,
        title: post.title,
        slug: post.slug,
        body: post.body,
        published: post.published,
        author_id: *post.author.id(),
        tags,
        created_at: post.created_at.to_rfc3339(),
        updated_at: post.updated_at.to_rfc3339(),
    })
}

/// The post `slug` as seen by `viewer`: drafts exist only for their author.
///
/// # Errors
/// `404` when there is no such post or the viewer may not see it.
pub async fn visible_post(db: &Db, slug: &str, viewer: Option<i64>) -> Result<Post, ApiError> {
    Post::objects(db)
        .filter(Post::slug.eq(slug.to_owned()))
        .first()
        .await?
        .filter(|post| post.published || viewer == Some(*post.author.id()))
        .ok_or_else(|| ApiError::not_found("Post not found."))
}

/// The post `slug`, which `user` must have written.
///
/// # Errors
/// `404` for an unknown or invisible post, `403` when it belongs to someone else.
async fn owned_post(db: &Db, slug: &str, user: &CurrentUser) -> Result<Post, ApiError> {
    let post = visible_post(db, slug, Some(user.id)).await?;
    if *post.author.id() == user.id {
        Ok(post)
    } else {
        Err(ApiError::new(
            siderite::http::StatusCode::FORBIDDEN,
            "Only the author may change this post.",
        ))
    }
}

/// List published posts, newest first, optionally by tag.
#[get("/posts", tag = "posts")]
async fn list_posts(
    Conn(db): Conn,
    Query(page): Query<PageParams>,
    Query(filter): Query<PostFilter>,
) -> Result<Json<Paginated<PostOut>>, ApiError> {
    let queryset = match filter.tag {
        Some(name) => match Tag::objects(&db).filter(Tag::name.eq(name)).first().await? {
            Some(tag) => tag.posts(&db),
            None => Post::objects(&db).none(),
        },
        None => Post::objects(&db),
    };
    let queryset = queryset.filter(Post::published.eq(true));
    let out = paginate(queryset, page, |post| post_out(&db, post)).await?;
    Ok(Json(out))
}

/// Create a post; requires the `posts:write` scope.
#[post("/posts", status = 201, tag = "posts")]
async fn create_post(
    Security(user, _): Security<CurrentUser, WritePosts>,
    Conn(db): Conn,
    Json(body): Json<NewPost>,
) -> Result<Json<PostOut>, ApiError> {
    let tags = clean_tags(&body.tags)?;
    let author = user.id;
    let post = db
        .transaction(|tx| async move {
            let mut post = Post {
                id: 0,
                slug: unique_slug(&tx, &body.title).await?,
                title: body.title,
                body: body.body,
                published: body.published,
                author: ForeignKey::new(author),
                created_at: Utc::now(),
                updated_at: Utc::now(),
            };
            post.save(&tx).await?;
            replace_tags(&tx, &post, &tags).await?;
            Ok::<_, ApiError>(post)
        })
        .await?;
    Ok(Json(post_out(&db, post).await?))
}

/// Fetch one post; drafts are visible to their author only.
#[get("/posts/{slug}", tag = "posts")]
async fn get_post(
    Conn(db): Conn,
    viewer: Option<Security<CurrentUser>>,
    Path(slug): Path<String>,
) -> Result<Json<PostOut>, ApiError> {
    let viewer = viewer.map(|Security(user, _)| user.id);
    let post = visible_post(&db, &slug, viewer).await?;
    Ok(Json(post_out(&db, post).await?))
}

/// Edit your own post; requires the `posts:write` scope.
#[patch("/posts/{slug}", tag = "posts")]
async fn patch_post(
    Security(user, _): Security<CurrentUser, WritePosts>,
    Conn(db): Conn,
    Path(slug): Path<String>,
    Json(body): Json<PatchPost>,
) -> Result<Json<PostOut>, ApiError> {
    let tags = body.tags.as_deref().map(clean_tags).transpose()?;
    let mut post = owned_post(&db, &slug, &user).await?;
    if let Some(title) = body.title {
        post.title = title;
    }
    if let Some(text) = body.body {
        post.body = text;
    }
    if let Some(published) = body.published {
        post.published = published;
    }
    let post = db
        .transaction(|tx| async move {
            post.save(&tx).await?;
            if let Some(tags) = tags {
                replace_tags(&tx, &post, &tags).await?;
            }
            Ok::<_, ApiError>(post)
        })
        .await?;
    Ok(Json(post_out(&db, post).await?))
}

/// Delete your own post and its comments; requires the `posts:write` scope.
#[delete("/posts/{slug}", tag = "posts")]
async fn delete_post(
    Security(user, _): Security<CurrentUser, WritePosts>,
    Conn(db): Conn,
    Path(slug): Path<String>,
) -> Result<NoContent, ApiError> {
    let post = owned_post(&db, &slug, &user).await?;
    db.transaction(|tx| async move { post.delete(&tx).await })
        .await?;
    Ok(NoContent)
}

/// List tags alphabetically.
#[get("/tags", tag = "tags")]
async fn list_tags(
    Conn(db): Conn,
    Query(page): Query<PageParams>,
) -> Result<Json<Paginated<TagOut>>, ApiError> {
    let out = paginate(Tag::objects(&db), page, |tag| async move {
        Ok(TagOut {
            id: tag.id,
            name: tag.name,
        })
    })
    .await?;
    Ok(Json(out))
}

/// Routes of this module.
pub fn routes() -> Vec<Route> {
    routes![
        list_posts,
        create_post,
        get_post,
        patch_post,
        delete_post,
        list_tags
    ]
    .into_iter()
    .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn slugs_are_lowercase_words_joined_by_dashes() {
        assert_eq!(slugify("Hello, World!"), "hello-world");
        assert_eq!(slugify("  Rust -- 2024  "), "rust-2024");
        assert_eq!(slugify("???"), "post");
    }

    #[test]
    fn tags_are_normalized_and_limited() {
        let names = ["Rust ", "rust", "", "Web"].map(String::from);
        assert_eq!(
            clean_tags(&names).ok(),
            Some(vec!["rust".into(), "web".into()])
        );
        let many: Vec<String> = (0..=MAX_TAGS).map(|n| format!("t{n}")).collect();
        assert!(clean_tags(&many).is_err());
        assert!(clean_tags(&["x".repeat(51)]).is_err());
    }
}

//! Model signal receivers: an audit trail for posts.

use crate::models::{AuditEntry, Post};
use siderite::orm::ModelOps;
use siderite::orm::signals::{SignalError, SignalEvent, SignalKind, Signals};
use siderite::prelude::*;
use siderite::receiver;

/// Append one [`AuditEntry`] through the handle of the operation, so the
/// entry commits or rolls back together with the change it describes.
async fn record(event: &SignalEvent<'_>, action: &str, post: &Post) -> Result<(), SignalError> {
    AuditEntry {
        id: 0,
        action: action.to_owned(),
        entity_id: post.id,
        created_at: Utc::now(),
    }
    .save(event.db)
    .await?;
    Ok(())
}

/// Log `post.created` and `post.updated`.
#[receiver(post_save, model = Post)]
pub async fn audit_post_saved(post: &Post, event: &SignalEvent<'_>) -> Result<(), SignalError> {
    let action = match event.kind {
        SignalKind::PostSave { created: true } => "post.created",
        _ => "post.updated",
    };
    record(event, action, post).await
}

/// Log `post.deleted`.
#[receiver(post_delete, model = Post)]
pub async fn audit_post_deleted(post: &Post, event: &SignalEvent<'_>) -> Result<(), SignalError> {
    record(event, "post.deleted", post).await
}

/// The registry with every receiver of the blog connected.
pub fn signals() -> Signals {
    let signals = Signals::new();
    signals.connect(audit_post_saved_receiver());
    signals.connect(audit_post_deleted_receiver());
    signals
}

//! Account registration and the profile of the caller.

use crate::auth::{CurrentUser, DEFAULT_SCOPES, hash_password};
use crate::db::Conn;
use crate::models::User;
use siderite::orm::ModelOps;
use siderite::prelude::*;
use siderite::security::Security;

/// Body of `POST /users`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct NewUser {
    /// Login name, 3 to 32 characters.
    #[field(min_length = 3, max_length = 32)]
    pub username: String,
    /// Password, at least 8 characters. Never stored or logged in the clear.
    #[field(min_length = 8, max_length = 128)]
    pub password: String,
}

/// Public view of an account: never includes the password digest.
#[derive(Debug, Serialize, Schema)]
pub struct UserOut {
    /// Database key.
    pub id: i64,
    /// Login name.
    pub username: String,
    /// Scopes the account may be granted.
    pub scopes: Vec<String>,
    /// When the account was created (RFC 3339).
    pub created_at: String,
}

impl From<User> for UserOut {
    fn from(user: User) -> Self {
        Self {
            id: user.id,
            username: user.username,
            scopes: user.scopes.split_whitespace().map(str::to_owned).collect(),
            created_at: user.created_at.to_rfc3339(),
        }
    }
}

/// Register an account.
#[post("/users", status = 201, tag = "users")]
async fn register(Conn(db): Conn, Json(body): Json<NewUser>) -> Result<Json<UserOut>, ApiError> {
    let mut user = User {
        id: 0,
        username: body.username,
        password_hash: hash_password(&body.password),
        scopes: DEFAULT_SCOPES.to_owned(),
        created_at: Utc::now(),
    };
    user.save(&db).await?;
    Ok(Json(user.into()))
}

/// The account behind the bearer token.
#[get("/users/me", tag = "users")]
async fn me(
    Security(current, _): Security<CurrentUser>,
    Conn(db): Conn,
) -> Result<Json<UserOut>, ApiError> {
    let user = User::objects(&db).get(User::id.eq(current.id)).await?;
    Ok(Json(user.into()))
}

/// Routes of this module.
pub fn routes() -> Vec<Route> {
    routes![register, me].into_iter().collect()
}

//! End-to-end tests on in-memory SQLite, using the generated migrations.
#![allow(clippy::unwrap_used)]

use blog_postgres::models::{AuditEntry, Comment, all_models};
use blog_postgres::{MIGRATIONS_DIR, app};
use http::{Method, Request, header};
use serde_json::{Value, json};
use siderite::Body;
use siderite::http::StatusCode;
use siderite::orm::Model;
use siderite_testkit::{TestClient, TestDatabase, TestResponse};

struct Fixture {
    client: TestClient,
    db: siderite::orm::Db,
}

async fn fixture() -> Fixture {
    let test = TestDatabase::sqlite_memory()
        .await
        .unwrap()
        .with_migrations(MIGRATIONS_DIR)
        .await
        .unwrap()
        .with_signals(blog_postgres::receivers::signals());
    let db = test.into_db();
    let client = TestClient::builder(app())
        .with_database("default", db.clone())
        .build();
    Fixture { client, db }
}

async fn send(
    client: &TestClient,
    method: Method,
    path: &str,
    token: Option<&str>,
    body: Option<Value>,
) -> TestResponse {
    let mut req = Request::builder().method(method).uri(path);
    if let Some(token) = token {
        req = req.header(header::AUTHORIZATION, format!("Bearer {token}"));
    }
    let body = match body {
        Some(value) => {
            req = req.header(header::CONTENT_TYPE, "application/json");
            Body::from(serde_json::to_vec(&value).unwrap())
        }
        None => Body::empty(),
    };
    client.send(req.body(body).unwrap()).await.unwrap()
}

async fn login(client: &TestClient, name: &str, scope: &str) -> TestResponse {
    let form = format!("username={name}&password=secret-pass&scope={scope}");
    let req = Request::builder()
        .method(Method::POST)
        .uri("/token")
        .header(header::CONTENT_TYPE, "application/x-www-form-urlencoded")
        .body(Body::from(form))
        .unwrap();
    client.send(req).await.unwrap()
}

/// Register `name` and return a token with all scopes.
async fn user_token(client: &TestClient, name: &str) -> String {
    let res = send(
        client,
        Method::POST,
        "/users",
        None,
        Some(json!({"username": name, "password": "secret-pass"})),
    )
    .await;
    assert_eq!(res.status, StatusCode::CREATED);
    let token = login(client, name, "").await;
    assert_eq!(token.status, StatusCode::OK);
    token.json::<Value>().unwrap()["access_token"]
        .as_str()
        .unwrap()
        .to_owned()
}

async fn new_post(client: &TestClient, token: &str, title: &str, published: bool) -> Value {
    let res = send(
        client,
        Method::POST,
        "/posts",
        Some(token),
        Some(json!({"title": title, "body": "text", "published": published, "tags": ["Rust", "web"]})),
    )
    .await;
    assert_eq!(res.status, StatusCode::CREATED, "{}", res.text());
    res.json().unwrap()
}

