//! Runs against a live MongoDB named by `MONGODB_URL`; without it the tests
//! print a notice and pass. Each test uses its own throw-away database.
#![allow(clippy::unwrap_used)]

use http::{Method, Request, header};
use serde_json::{Value, json};
use siderite::Body;
use siderite::http::StatusCode;
use siderite_testkit::{TestClient, TestResponse};
use todo_mongo::{app, open_db};

/// A client on a fresh database, plus the URL and name to drop afterwards.
async fn client() -> Option<(TestClient, String, String)> {
    let Ok(url) = std::env::var("MONGODB_URL") else {
        eprintln!("MONGODB_URL not set: skipping");
        return None;
    };
    let name = format!(
        "todo_test_{}",
        std::process::id() as u64 * 1000 + rand_suffix()
    );
    let db = open_db(&url, &name).await.unwrap();
    Some((TestClient::new(app(db)), url, name))
}

fn rand_suffix() -> u64 {
    use std::sync::atomic::{AtomicU64, Ordering};
    static NEXT: AtomicU64 = AtomicU64::new(0);
    NEXT.fetch_add(1, Ordering::SeqCst)
}

async fn cleanup(url: &str, name: &str) {
    let backend = siderite_backends::mongodb::MongoBackend::connect(url, name)
        .await
        .unwrap();
    backend.database().drop().await.unwrap();
}

async fn send(
    client: &TestClient,
    method: Method,
    path: &str,
    body: Option<Value>,
) -> TestResponse {
    let mut req = Request::builder().method(method).uri(path);
    let body = match body {
        Some(value) => {
            req = req.header(header::CONTENT_TYPE, "application/json");
            Body::from(serde_json::to_vec(&value).unwrap())
        }
        None => Body::empty(),
    };
    client.send(req.body(body).unwrap()).await.unwrap()
}

#[tokio::test]
async fn crud_round_trip() {
    let Some((client, url, name)) = client().await else {
        return;
    };

    let created = client
        .post_json("/todos", &json!({"title": "write docs"}))
        .await
        .unwrap();
    assert_eq!(created.status, StatusCode::CREATED);
    let todo: Value = created.json().unwrap();
    assert_eq!(todo["done"], false);
    let id = todo["id"].as_i64().unwrap();

    let fetched = client.get(&format!("/todos/{id}")).await.unwrap();
    assert_eq!(fetched.json::<Value>().unwrap()["title"], "write docs");

    let patched = send(
        &client,
        Method::PATCH,
        &format!("/todos/{id}"),
        Some(json!({"done": true})),
    )
    .await;
    assert_eq!(patched.status, StatusCode::OK);
    assert_eq!(patched.json::<Value>().unwrap()["done"], true);

    let deleted = send(&client, Method::DELETE, &format!("/todos/{id}"), None).await;
    assert_eq!(deleted.status, StatusCode::NO_CONTENT);
    assert_eq!(
        client.get(&format!("/todos/{id}")).await.unwrap().status,
        StatusCode::NOT_FOUND
    );
    assert_eq!(
        send(&client, Method::DELETE, &format!("/todos/{id}"), None)
            .await
            .status,
        StatusCode::NOT_FOUND
    );
    cleanup(&url, &name).await;
}

#[tokio::test]
async fn generated_keys_filters_paging_and_stats() {
    let Some((client, url, name)) = client().await else {
        return;
    };
    let mut ids = Vec::new();
    for n in 1..=5 {
        let res = client
            .post_json("/todos", &json!({"title": format!("item {n}")}))
            .await
            .unwrap();
        ids.push(res.json::<Value>().unwrap()["id"].as_i64().unwrap());
    }
    assert!(
        ids.windows(2).all(|w| w[0] < w[1]),
        "keys increase: {ids:?}"
    );
    for id in &ids[..2] {
        send(
            &client,
            Method::PATCH,
            &format!("/todos/{id}"),
            Some(json!({"done": true})),
        )
        .await;
    }

    let done: Vec<Value> = client
        .get("/todos?done=true")
        .await
        .unwrap()
        .json()
        .unwrap();
    assert_eq!(done.len(), 2);
    let page: Vec<Value> = client
        .get("/todos?limit=2&offset=2")
        .await
        .unwrap()
        .json()
        .unwrap();
    let titles: Vec<&str> = page.iter().map(|t| t["title"].as_str().unwrap()).collect();
    assert_eq!(titles, ["item 3", "item 4"]);
    let stats: Value = client.get("/todos/stats").await.unwrap().json().unwrap();
    assert_eq!(stats, json!({"total": 5, "done": 2}));
    assert_eq!(
        client.get("/todos?limit=1000").await.unwrap().status,
        StatusCode::UNPROCESSABLE_ENTITY
    );
    cleanup(&url, &name).await;
}

#[tokio::test]
async fn empty_title_is_422() {
    let Some((client, url, name)) = client().await else {
        return;
    };
    let res = client
        .post_json("/todos", &json!({"title": ""}))
        .await
        .unwrap();
    assert_eq!(res.status, StatusCode::UNPROCESSABLE_ENTITY);
    cleanup(&url, &name).await;
}

//! SQLite-backed todo API: models, routes and an [`App`] factory.

use siderite::cache::{MemoryCache, RouteCache};
use siderite::prelude::*;
use siderite_backends::sqlite::SqliteBackend;
use std::time::Duration;

const SCHEMA: &str = "
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS todos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    done INTEGER NOT NULL,
    owner_id INTEGER NOT NULL REFERENCES users(id)
);
";

/// A person who owns todos.
#[derive(Debug, Clone, Model, Serialize, Deserialize, Validate, Schema)]
#[model(table = "users")]
pub struct User {
    /// Database key.
    #[field(primary_key, auto)]
    #[serde(default)]
    pub id: i64,
    /// Display name.
    #[field(min_length = 1, max_length = 100)]
    pub name: String,
}

/// A todo item owned by a [`User`].
#[derive(Debug, Clone, Model, Serialize, Deserialize, Validate, Schema)]
#[model(table = "todos", ordering = ["id"])]
pub struct Todo {
    /// Database key.
    #[field(primary_key, auto)]
    #[serde(default)]
    pub id: i64,
    /// What to do.
    #[field(min_length = 1, max_length = 280)]
    pub title: String,
    /// Whether the item is complete.
    pub done: bool,
    /// Owner of the item.
    #[field(related_name = "todos")]
    pub owner: ForeignKey<User>,
}

/// Body of `POST /users`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct NewUser {
    /// Display name.
    #[field(min_length = 1, max_length = 100)]
    pub name: String,
}

/// Body of `POST /todos`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct NewTodo {
    /// What to do.
    #[field(min_length = 1, max_length = 280)]
    pub title: String,
    /// Owner primary key.
    pub owner: ForeignKey<User>,
}

/// Body of `PATCH /todos/{id}`.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct PatchTodo {
    /// Replacement title.
    #[field(min_length = 1, max_length = 280)]
    pub title: Option<String>,
    /// Replacement completion flag.
    pub done: Option<bool>,
}

/// Open a SQLite database and create the todo tables.
///
/// # Errors
/// Connection or DDL failures, mapped to an internal API error.
pub async fn open_db(url: &str) -> Result<Db, ApiError> {
    let backend = SqliteBackend::connect(url)
        .await
        .map_err(ApiError::internal)?;
    let db = Db::new(backend);
    db.execute_script(SCHEMA)
        .await
        .map_err(ApiError::internal)?;
    Ok(db)
}

/// Application serving the todo API against `db`.
pub fn app(db: Db) -> App {
    App::new()
        .title("Todo")
        .version("1.0.0")
        .provide(db)
        .routes(routes![
            create_user,
            list_todos,
            create_todo,
            get_todo,
            patch_todo,
            delete_todo
        ])
        // Stores only responses that opt in with `Cache-Control: public`.
        .layer(RouteCache::new(MemoryCache::new(256)))
}

/// Create a user.
#[post("/users", status = 201)]
async fn create_user(db: Provided<Db>, Json(body): Json<NewUser>) -> Result<Json<User>, ApiError> {
    let user = User::objects(&db)
        .create(User {
            id: 0,
            name: body.name,
        })
        .await?;
    Ok(Json(user))
}

/// List every todo, oldest first.
///
/// Cached for a few seconds to show `RouteCache`: the list may lag behind
/// writes by up to that long, since nothing invalidates it.
#[get("/todos")]
async fn list_todos(db: Provided<Db>) -> Result<Cached<Json<Vec<Todo>>>, ApiError> {
    let todos = Todo::objects(&db).all().await?;
    Ok(Cached::public(Duration::from_secs(5), Json(todos)))
}

/// Create a todo.
#[post("/todos", status = 201)]
async fn create_todo(db: Provided<Db>, Json(body): Json<NewTodo>) -> Result<Json<Todo>, ApiError> {
    let todo = Todo::objects(&db)
        .create(Todo {
            id: 0,
            title: body.title,
            done: false,
            owner: body.owner,
        })
        .await?;
    Ok(Json(todo))
}

/// Fetch one todo.
#[get("/todos/{id}")]
async fn get_todo(db: Provided<Db>, Path(id): Path<i64>) -> Result<Json<Todo>, ApiError> {
    Ok(Json(Todo::objects(&db).get(Todo::id.eq(id)).await?))
}

/// Patch title and/or completion of a todo.
#[patch("/todos/{id}")]
async fn patch_todo(
    db: Provided<Db>,
    Path(id): Path<i64>,
    Json(body): Json<PatchTodo>,
) -> Result<Json<Todo>, ApiError> {
    let mut todo = Todo::objects(&db).get(Todo::id.eq(id)).await?;
    if let Some(title) = body.title {
        todo.title = title;
    }
    if let Some(done) = body.done {
        todo.done = done;
    }
    todo.save(&db).await?;
    Ok(Json(todo))
}

/// Delete a todo.
#[delete("/todos/{id}")]
async fn delete_todo(db: Provided<Db>, Path(id): Path<i64>) -> Result<NoContent, ApiError> {
    let n = Todo::objects(&db).filter(Todo::id.eq(id)).delete().await?;
    if n == 0 {
        return Err(ApiError::not_found("todo not found"));
    }
    Ok(NoContent)
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]

    use super::*;
    use http::{Method, Request, header};
    use serde_json::{Value, json};
    use siderite::Body;
    use siderite::http::StatusCode;
    use siderite_testkit::TestClient;

    async fn client() -> TestClient {
        let db = open_db("sqlite::memory:").await.unwrap();
        TestClient::new(app(db))
    }

    async fn send_json(
        client: &TestClient,
        method: Method,
        path: &str,
        body: &Value,
    ) -> siderite_testkit::TestResponse {
        let req = Request::builder()
            .method(method)
            .uri(path)
            .header(header::CONTENT_TYPE, "application/json")
            .body(Body::from(serde_json::to_vec(body).unwrap()))
            .unwrap();
        client.send(req).await.unwrap()
    }

    #[tokio::test]
    async fn crud_round_trip() {
        let client = client().await;

        let created_user = client
            .post_json("/users", &json!({"name": "Ann"}))
            .await
            .unwrap();
        assert_eq!(created_user.status, StatusCode::CREATED);
        let user: Value = created_user.json().unwrap();
        let owner = user["id"].clone();

        let created = client
            .post_json("/todos", &json!({"title": "write docs", "owner": owner}))
            .await
            .unwrap();
        assert_eq!(created.status, StatusCode::CREATED);
        let todo: Value = created.json().unwrap();
        assert_eq!(todo["title"], "write docs");
        assert_eq!(todo["done"], false);
        let id = todo["id"].as_i64().unwrap();

        let listed = client.get("/todos").await.unwrap();
        assert_eq!(listed.status, StatusCode::OK);
        let items: Vec<Value> = listed.json().unwrap();
        assert_eq!(items.len(), 1);

        let fetched = client.get(&format!("/todos/{id}")).await.unwrap();
        assert_eq!(fetched.status, StatusCode::OK);
        assert_eq!(fetched.json::<Value>().unwrap()["title"], "write docs");

        let patched = send_json(
            &client,
            Method::PATCH,
            &format!("/todos/{id}"),
            &json!({"done": true}),
        )
        .await;
        assert_eq!(patched.status, StatusCode::OK);
        assert_eq!(patched.json::<Value>().unwrap()["done"], true);

        let deleted = client
            .send(
                Request::builder()
                    .method(Method::DELETE)
                    .uri(format!("/todos/{id}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(deleted.status, StatusCode::NO_CONTENT);

        let missing = client.get(&format!("/todos/{id}")).await.unwrap();
        assert_eq!(missing.status, StatusCode::NOT_FOUND);
    }

    #[tokio::test]
    async fn todo_list_is_cached_and_other_routes_are_not() {
        let client = client().await;
        let first = client.get("/todos").await.unwrap();
        assert_eq!(first.headers["x-cache"], "miss");
        assert_eq!(first.headers["cache-control"], "public, max-age=5");
        let second = client.get("/todos").await.unwrap();
        assert_eq!(second.headers["x-cache"], "hit");

        let missing = client.get("/todos/999").await.unwrap();
        assert_eq!(missing.status, StatusCode::NOT_FOUND);
        let again = client.get("/todos/999").await.unwrap();
        assert_eq!(again.headers["x-cache"], "miss");
    }

    #[tokio::test]
    async fn empty_title_is_422() {
        let client = client().await;
        let user = client
            .post_json("/users", &json!({"name": "Ann"}))
            .await
            .unwrap()
            .json::<Value>()
            .unwrap();
        let res = client
            .post_json("/todos", &json!({"title": "", "owner": user["id"]}))
            .await
            .unwrap();
        assert_eq!(res.status, StatusCode::UNPROCESSABLE_ENTITY);
    }
}

//! SQLite-backed todo API.

use siderite::prelude::*;
use siderite_cli::{AppCli, CliSettings};
use todo_sqlite::{Todo, User, app, open_db};

#[tokio::main]
async fn main() -> std::process::ExitCode {
    let url = std::env::var("DATABASE_URL").unwrap_or_else(|_| "sqlite://todo.db?mode=rwc".into());
    let db = match open_db(&url).await {
        Ok(db) => db,
        Err(err) => {
            eprintln!("{err}");
            return std::process::ExitCode::from(1);
        }
    };
    AppCli::new(move || app(db.clone()))
        .models(&[User::META, Todo::META])
        .settings(CliSettings::new().database("default", url))
        .run()
        .await
}

use super::model::Product;
use siderite::prelude::*;
use siderite_cli::{AppCli, CliSettings};

/// The command line: `siderite run`, `check`, `migrate`, ... all go
/// through `AppCli`, which knows the app factory and the models.
#[tokio::main]
pub async fn main() -> std::process::ExitCode {
    let settings = match siderite::config::load() {
        Ok(settings) => CliSettings::from(&settings),
        Err(err) => {
            eprintln!("{err}");
            return std::process::ExitCode::from(1);
        }
    };
    AppCli::new(|| App::new().title("Shop"))
        .models(&[Product::META])
        .settings(settings)
        .migrations_dir("migrations")
        .run()
        .await
}

use siderite::prelude::*;

/// A product row; `makemigrations` turns changes into migrations.
#[derive(Debug, Clone, Model, Serialize, Deserialize, Validate, Schema)]
#[model(table = "products", ordering = ["id"])]
pub struct Product {
    /// Database key, assigned on insert.
    #[field(primary_key, auto)]
    #[serde(default)]
    pub id: i64,
    /// Display name.
    #[field(min_length = 1, max_length = 100)]
    pub name: String,
    /// Whether it can be ordered.
    pub in_stock: bool,
}

/// List the products in stock with one query.
#[get("/products")]
pub async fn list_products(db: Provided<Db>) -> ApiResult<Json<Vec<Product>>> {
    let query = Product::objects(&db).filter(Product::in_stock.eq(true));
    Ok(Json(query.all().await?))
}

use siderite::prelude::*;

/// Body of `POST /notes`; invalid input is answered with 422.
#[derive(Debug, Deserialize, Validate, Schema)]
pub struct NewNote {
    /// Note text.
    #[field(min_length = 1, max_length = 500)]
    pub text: String,
}

/// A note in responses.
#[derive(Debug, Serialize, Schema)]
pub struct Note {
    /// Identifier.
    pub id: i64,
    /// Note text.
    pub text: String,
}

/// Fetch one note.
#[get("/notes/{id}", tag = "notes")]
pub async fn get_note(Path(id): Path<i64>) -> Result<Json<Note>, ApiError> {
    if id != 1 {
        return Err(ApiError::not_found("note not found"));
    }
    let text = "hello".to_owned();
    Ok(Json(Note { id, text }))
}

/// Create a note.
#[post("/notes", status = 201, tag = "notes")]
pub async fn create_note(Json(body): Json<NewNote>) -> Json<Note> {
    Json(Note {
        id: 1,
        text: body.text,
    })
}

/// The application factory: every route is registered explicitly.
pub fn app() -> App {
    App::new()
        .title("Notes")
        .version("0.1.0")
        .routes(routes![get_note, create_note])
}
